from solution import valid_date
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref(date):
    """Obviously-correct reference derived directly from spec."""
    if not isinstance(date, str):
        return False
    if len(date) == 0:
        return False
    if len(date) != 10:
        return False
    if date[2] != '-' or date[5] != '-':
        return False
    m_s, d_s, y_s = date[:2], date[3:5], date[6:]
    if not (m_s.isdigit() and d_s.isdigit() and y_s.isdigit()):
        return False
    m = int(m_s)
    d = int(d_s)
    if not (1 <= m <= 12):
        return False
    if m in (1, 3, 5, 7, 8, 10, 12):
        max_d = 31
    elif m in (4, 6, 9, 11):
        max_d = 30
    else:  # m == 2
        max_d = 29
    if not (1 <= d <= max_d):
        return False
    return True


# ---- concrete examples from spec ----

def test_example_valid_march():
    assert valid_date('03-11-2000') is True

def test_example_month_15_invalid():
    assert valid_date('15-01-2012') is False

def test_example_day_zero_short_length():
    assert valid_date('04-0-2040') is False

def test_example_valid_june():
    assert valid_date('06-04-2020') is True

def test_example_wrong_separator():
    assert valid_date('06/04/2020') is False


# ---- empty / length / format ----

def test_empty_string_is_invalid():
    assert valid_date('') is False

def test_length_not_10_is_invalid():
    for s in ['', '0', '03-11-2000 ', ' 03-11-2000', '03-11-200', '03-11-20000',
              '3-11-2000', '03-1-2000', '04-0-2040', '1-1-2000', '03-11-00']:
        assert valid_date(s) is False, s

def test_separators_must_be_dashes():
    for s in ['06/04/2020', '06.04.2020', '06:04:2020', '06 04 2020',
              '06-04/2020', '06/04-2020', '--04-2020', '06---2020']:
        assert valid_date(s) is False, s

def test_non_digit_components_are_invalid():
    for s in ['ab-cd-efgh', '0a-11-2000', '03-1a-2000', '03-11-20a0',
              ' 3-11-2000', '03-11-200 ', 'MM-DD-YYYY', '03-11-20 0']:
        assert valid_date(s) is False, s

def test_single_digit_month_day_missing_leading_zero_invalid():
    # format is strictly mm-dd-yyyy
    assert valid_date('3-11-2000') is False
    assert valid_date('03-1-2000') is False
    assert valid_date('6-4-2020') is False


# ---- month boundaries ----

def test_month_zero_is_invalid():
    assert valid_date('00-11-2000') is False

def test_month_13_is_invalid():
    assert valid_date('13-11-2000') is False

def test_month_13_does_not_raise():
    try:
        r = valid_date('13-01-2000')
    except Exception as e:
        pytest.fail(f"month 13 should return False, raised {type(e).__name__}: {e}")
    assert r is False

def test_month_above_12_always_invalid():
    for m in ['13', '14', '15', '19', '20', '99', '00']:
        s = f"{m}-01-2000"
        assert len(s) == 10
        assert valid_date(s) is False, s

def test_month_12_boundary_valid():
    assert valid_date('12-31-2000') is True
    assert valid_date('12-01-1999') is True
    assert valid_date('01-31-2000') is True

def test_month_12_day_32_invalid():
    assert valid_date('12-32-2000') is False


# ---- day boundaries per month class ----

def test_day_zero_invalid_all_months():
    for m in ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12']:
        assert valid_date(f"{m}-00-2000") is False, m

def test_february_29_valid_30_invalid():
    assert valid_date('02-29-2000') is True
    assert valid_date('02-30-2000') is False
    assert valid_date('02-31-2000') is False
    assert valid_date('02-01-2000') is True
    assert valid_date('02-00-2000') is False

def test_30_day_months_31_invalid():
    for m in ['04', '06', '09', '11']:
        assert valid_date(f"{m}-30-2000") is True, m
        assert valid_date(f"{m}-31-2000") is False, m
        assert valid_date(f"{m}-01-2000") is True, m
        assert valid_date(f"{m}-00-2000") is False, m

def test_31_day_months_31_valid_32_invalid():
    for m in ['01', '03', '05', '07', '08', '10', '12']:
        assert valid_date(f"{m}-31-2000") is True, m
        assert valid_date(f"{m}-32-2000") is False, m
        assert valid_date(f"{m}-00-2000") is False, m


# ---- property-based: equivalence to reference ----

valid_months = st.sampled_from(['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12'])
valid_days = st.integers(min_value=1, max_value=28).map(lambda n: f"{n:02d}")
years = st.integers(min_value=0, max_value=9999).map(lambda n: f"{n:04d}")

@given(m=valid_months, d=valid_days, y=years)
def test_property_all_days_01_to_28_always_valid(m, d, y):
    s = f"{m}-{d}-{y}"
    assert valid_date(s) is True, s

@given(m=st.integers(min_value=0, max_value=99).map(lambda n: f"{n:02d}"),
       d=st.integers(min_value=0, max_value=99).map(lambda n: f"{n:02d}"),
       y=st.integers(min_value=0, max_value=9999).map(lambda n: f"{n:04d}"))
def test_property_equivalence_to_reference_on_shaped_inputs(m, d, y):
    s = f"{m}-{d}-{y}"
    assert valid_date(s) == ref(s), s

@given(st.text(alphabet=st.sampled_from(list("0123456789-/abc .:\n")), min_size=0, max_size=12))
def test_property_equivalence_to_reference_on_arbitrary_short_strings(s):
    assert valid_date(s) == ref(s), repr(s)

@given(st.integers(min_value=0, max_value=31))
def test_property_day_sweep_january(n):
    s = f"01-{n:02d}-2000"
    expected = (1 <= n <= 31)
    assert valid_date(s) == expected, s

@given(st.integers(min_value=0, max_value=31))
def test_property_day_sweep_february(n):
    s = f"02-{n:02d}-2000"
    expected = (1 <= n <= 29)
    assert valid_date(s) == expected, s

@given(st.integers(min_value=0, max_value=31))
def test_property_day_sweep_april(n):
    s = f"04-{n:02d}-2000"
    expected = (1 <= n <= 30)
    assert valid_date(s) == expected, s

@given(st.integers(min_value=0, max_value=20))
def test_property_month_sweep_day_15(m):
    s = f"{m:02d}-15-2000"
    expected = (1 <= m <= 12)
    assert valid_date(s) == expected, s

@given(st.integers(min_value=0, max_value=20))
def test_property_month_sweep_never_raises(m):
    s = f"{m:02d}-15-2000"
    try:
        r = valid_date(s)
    except Exception as e:
        pytest.fail(f"should return bool not raise for {s!r}: {e}")
    assert r == ref(s)

def test_property_returns_bool_not_truthy():
    for s in ['03-11-2000', '15-01-2012', '', '06/04/2020', '13-01-2000', '02-29-2000', '02-30-2000']:
        assert valid_date(s) is True or valid_date(s) is False, s
